import AuthenticationServices
import SwiftUI

/// One record read from its operation, its sections shown read-only, a
/// field hidden while its rule holds, with the actions that open a page,
/// offered to whoever holds their permission, and those that run an
/// operation on the record, each after its confirmation with the reason
/// it requires; a success says its message and reads the record again.
public struct ViewPage: View {
    let schema: ViewPageSchema
    /// The page's route parameters.
    let parameters: [String: String]
    /// The routes the page's actions lead to, by the page each names.
    let routes: [String: Routes.Make]
    @Environment(Router.self) private var router
    @Environment(\.webAuthenticationSession) private var webAuthenticationSession
    @AppStorage(Strings.languageKey) private var language = Strings.languages[0]
    @State private var record: Fields?
    @State private var loadFailed: String?
    @State private var failed: String?
    @State private var reload = 0
    @State private var confirming: Confirming?
    @State private var reason = ""
    @State private var running = false

    public init(schema: ViewPageSchema, parameters: [String: String], routes: [String: Routes.Make]) {
        self.schema = schema
        self.parameters = parameters
        self.routes = routes
    }

    public var body: some View {
        let texts = Strings.texts(language)
        List {
            if let loadFailed {
                Text(loadFailed).foregroundStyle(.red)
            } else if let record {
                if let failed {
                    Text(failed).foregroundStyle(.red)
                }
                ForEach(Array(schema.sections.enumerated()), id: \.offset) { _, section in
                    Section(section.title.map { say(texts, $0) } ?? "") {
                        ForEach(section.fields.filter { !Rules.hidden($0.hiddenWhen, record) }, id: \.name) { field in
                            ViewFieldView(field: field, value: record[field.name], texts: texts)
                        }
                    }
                }
                let operations = schema.operations.filter { Actions.offered($0, record) }
                if !operations.isEmpty {
                    Section {
                        ForEach(operations, id: \.label) { action in
                            Button(say(texts, action.label), role: action.confirm == nil ? nil : .destructive) {
                                reason = ""
                                if action.confirm == nil {
                                    Task { await run(action, record, texts) }
                                } else {
                                    confirming = Confirming(action: action, record: record)
                                }
                            }
                        }
                    }
                }
            } else {
                ProgressView(say(texts, "screens.loading"))
            }
        }
        .navigationTitle(say(texts, schema.title))
        .toolbar {
            ToolbarItem {
                Menu(say(texts, "screens.actions")) {
                    ForEach(schema.actions.filter { Actions.holds($0.permission) }, id: \.navigate) { action in
                        if let make = routes[action.navigate] {
                            Button(say(texts, action.label)) {
                                var from = parameters
                                for (name, value) in record ?? [:] {
                                    from[name] = value.text
                                }
                                router.go(to: make(from))
                            }
                        }
                    }
                }
            }
        }
        .task(id: reload) { await load(texts) }
        .confirming($confirming, reason: $reason, texts: texts, running: running) { confirming in
            Task { await run(confirming.action, confirming.record, texts) }
        }
        .overlay(alignment: .top) { NoticeView() }
    }

    @MainActor
    private func load(_ texts: Texts) async {
        do {
            let answer = try await Service.send("GET", schema.source.path, parameters: parameters)
            guard answer.ok, case .object(let members)? = answer.body else {
                loadFailed = say(texts, Actions.refusal(schema.source.failed ?? [], answer.status)?.message ?? "screens.failed")
                return
            }
            loadFailed = nil
            record = members
        } catch {
            loadFailed = say(texts, "screens.failed")
        }
    }

    @MainActor
    private func run(_ action: RowActionSchema, _ record: Fields, _ texts: Texts) async {
        if action.reason != nil, reason.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return
        }
        running = true
        let refused = await Actions.run(action, record, reason: reason, texts)
        running = false
        confirming = nil
        reason = ""
        if let refused {
            failed = refused
            return
        }
        failed = nil
        if let callback = action.signIn {
            failed = await IdentityProvider.signInAndReturn(callback: callback, session: webAuthenticationSession, router: router)
            return
        }
        if let message = action.message {
            router.leave(say(texts, message), at: nil)
        }
        reload += 1
    }
}

/// A field as the view shows it: a label and its value, a value of a
/// schema part by part under its label, and a list of them item by item.
struct ViewFieldView: View {
    let field: ViewFieldSchema
    let value: JSON?
    let texts: Texts

    var body: some View {
        if let parts = field.parts {
            let items: [JSON] = field.list == true ? (value?.items ?? []) : (value.map { [$0] } ?? [])
            VStack(alignment: .leading, spacing: 2) {
                Text(say(texts, field.label)).font(.subheadline).foregroundStyle(.secondary)
                if items.isEmpty {
                    Text(say(texts, "screens.none"))
                }
                ForEach(Array(items.enumerated()), id: \.offset) { _, item in
                    ForEach(parts, id: \.name) { part in
                        ViewFieldView(field: part, value: item[part.name], texts: texts)
                    }
                }
            }
        } else {
            LabeledContent(say(texts, field.label), value: Rows.shown(value, texts))
        }
    }
}
